package sh.pug.gentrack

private const val MAX_LINE = 120
private const val HEADER =
    "// Generated by tools/gen-track from proto/common/events/v1. Do not edit: run `make typed-track`."

// Events Pug tracks on its own get no method or class: tracking one would count it twice, and
// a screenView() would look like Pug.screen() without moving the current screen.
private val SDK_TRACKED = setOf("app_open", "app_close", "app_install", "app_update", "screen_view")

private val TRACK_NAMESPACE_DOC =
    listOf(
        "The well-known events, one method each but for those below. " +
            "`Pug.track.addToCart(productId = \"p1\", price = 9.99)` tracks `add_to_cart` with the properties " +
            "`productId` and `price`: properties without a default are those the event requires, and an argument " +
            "left null is not sent. For an event with properties the arguments must be named ([NamedArguments]): " +
            "a call that passes them by position does not compile, so two of one type cannot swap places.",
        "",
        "The events Pug tracks on its own have no method here: `app_open`, `app_close`, `app_install`, " +
            "`app_update`, and `screen_view`, which [Pug.screen] tracks for screens that are not activities.",
        "",
        "Every method also takes `extras`, more properties for the event (an entry named like an argument that is " +
            "set is dropped with a warning), and `options`, as `Pug.track(kind, properties, options)` does. Like " +
            "every call to [Pug], these return at once and never throw.",
        "",
        "Java sees only the methods of the events without properties, such as `Pug.track.signup()`: for the " +
            "others it tracks an object of `sh.pug.android.events`, such as " +
            "`Pug.track(new AddToCartEvent().productId(\"p1\"))`.",
    )

private const val EVENTS_DOC =
    "The kinds of Pug's well-known events, for `Pug.track(kind, properties)` and for comparisons. " +
        "[TrackNamespace] has a method for each but those Pug tracks itself, which takes the event's properties " +
        "as typed arguments; from Java, an event with properties is an object of `sh.pug.android.events`."

/** The generated sources, by their path under the SDK's Kotlin source root. */
fun render(events: List<Event>): Map<String, String> = mapOf(
    "sh/pug/android/TrackNamespace.kt" to trackNamespace(events),
    "sh/pug/android/Events.kt" to eventKinds(events),
    "sh/pug/android/events/Events.kt" to eventClasses(events),
    "sh/pug/android/internal/event/WellKnownEvents.kt" to wellKnownEvents(events),
)

private fun trackNamespace(events: List<Event>): String = buildString {
    preamble("sh.pug.android")
    appendLine("import sh.pug.android.internal.event.WellKnownEvents")
    appendLine("import sh.pug.android.internal.runtime.Facade")
    appendLine()
    kdoc("", TRACK_NAMESPACE_DOC.flatMap { if (it.isEmpty()) listOf(it) else wrap(it, "") })
    appendLine("public class TrackNamespace internal constructor(private val facade: Facade) {")
    events.filterNot { it.kind in SDK_TRACKED }.forEachIndexed { index, event ->
        if (index > 0) appendLine()
        method(event)
    }
    appendLine("}")
}

private fun StringBuilder.method(event: Event) {
    val doc = mutableListOf("Tracks `${event.kind}`.")
    if (event.comment.isNotEmpty()) doc += listOf("") + event.comment
    val tags = event.fields.flatMap { field -> parameterDoc(field)?.let { wrap(it, "    ", "  ") }.orEmpty() }
    if (tags.isNotEmpty()) doc += listOf("") + tags
    kdoc("    ", doc)
    // Java tracks an event with properties as an object instead, so it sees one typed form.
    appendLine(if (event.fields.isEmpty()) "    @JvmOverloads" else "    @JvmSynthetic")
    // Every argument after a vararg must be named, and NamedArguments has no instance to pass, so
    // property values cannot swap places. An event without properties gets no marker: its extras
    // and options differ in type, and Java calls its method.
    val marker = if (event.fields.isEmpty()) emptyList() else listOf("vararg named: NamedArguments")
    // In schema order, required or not: a compiled call passes them by position, so a property
    // that becomes required or optional keeps its place.
    val properties =
        event.fields.map { field ->
            val type = field.type.kotlin
            if (field.required) "${field.parameter}: $type" else "${field.parameter}: $type? = null"
        }
    val parameters = marker + properties + listOf("extras: Map<String, Any?>? = null", "options: TrackOptions? = null")
    wrapped("    ", "public fun ${event.method}(", parameters, ") {")
    val arguments = listOf("WellKnownEvents.${event.constant}", "extras", "options") + event.fields.map { it.parameter }
    wrapped("        ", "facade.trackTyped(", arguments, ")")
    appendLine("    }")
}

private fun parameterDoc(field: Field): String? {
    val notes =
        listOfNotNull(
            "in milliseconds, sent as `${field.key}` in seconds, such as `\"1.5s\"`"
                .takeIf { field.type == FieldType.DURATION },
            "personal data, as the event schema marks it".takeIf { field.pii },
        )
    return if (notes.isEmpty()) null else "@param ${field.parameter} ${notes.joinToString("; ")}."
}

// A class for each event with properties that has a method: without named arguments, Java
// would pass the method a row of nulls, so the method is hidden from it. Events without properties need none.
private fun eventClasses(events: List<Event>): String = buildString {
    preamble("sh.pug.android.events")
    appendLine("import sh.pug.android.internal.event.WellKnownEvents")
    events.filter { it.kind !in SDK_TRACKED && it.fields.isNotEmpty() }.forEach { event ->
        appendLine()
        eventClass(event)
    }
}

// Java has no named arguments, so every property is a setter, required ones too: a constructor
// taking them would let two of one type swap places.
private fun StringBuilder.eventClass(event: Event) {
    val name = event.className
    val required = event.fields.filter { it.required }.map { "`${it.parameter}`" }
    val doc =
        wrap(
            "The `${event.kind}` event, for `Pug.track(event)`. From Kotlin, `Pug.track.${event.method}(…)` takes " +
                "the same properties as named arguments.",
            "",
        ).toMutableList()
    if (required.isNotEmpty()) doc += listOf("") + wrap(requiredDoc(required), "")
    if (event.comment.isNotEmpty()) doc += listOf("") + event.comment
    kdoc("", doc)
    val open = "public class $name"
    val superclass = "WellKnownEvent(WellKnownEvents.${event.constant}, \"$name\")"
    // ktlint's layout: the superclass moves to its own line.
    if ("$open : $superclass {".length <= MAX_LINE) {
        appendLine("$open : $superclass {")
    } else {
        appendLine("$open :\n    $superclass {")
    }
    event.fields.forEachIndexed { index, field ->
        parameterDoc(field)?.let { kdoc("    ", wrap(it, "    ", "  ")) }
        val type = if (field.type == FieldType.STRING && !field.required) "String?" else field.type.kotlin
        val signature = "    public fun ${field.parameter}(${field.parameter}: $type): $name ="
        val body = "apply { values[$index] = ${field.parameter} }"
        if ("$signature $body".length <=
            MAX_LINE
        ) {
            appendLine("$signature $body")
        } else {
            appendLine("$signature\n        $body")
        }
        appendLine()
    }
    appendLine("    public fun extra(key: String, value: Any?): $name = apply { putExtra(key, value) }")
    appendLine("}")
}

private fun requiredDoc(names: List<String>): String = if (names.size == 1) {
    "${names[0]} is required: an event tracked without it is dropped with a warning."
} else {
    "${names.dropLast(1).joinToString(", ")} and ${names.last()} are required: an event tracked with any of them " +
        "unset is dropped with a warning."
}

private fun eventKinds(events: List<Event>): String = buildString {
    preamble("sh.pug.android")
    kdoc("", wrap(EVENTS_DOC, ""))
    appendLine("public object Events {")
    events.forEach { appendLine("    public const val ${it.constant}: String = \"${it.kind}\"") }
    appendLine("}")
}

private fun wellKnownEvents(events: List<Event>): String = buildString {
    preamble("sh.pug.android.internal.event")
    appendLine("import sh.pug.android.Events")
    events.flatMap { event -> event.fields.map { it.type.schema } }.toSortedSet().forEach {
        appendLine("import sh.pug.android.internal.event.FieldType.$it")
    }
    appendLine()
    kdoc("", listOf("The schema of each well-known event, for typed tracking and the checks on untyped events."))
    appendLine("internal object WellKnownEvents {")
    for (event in events) {
        val fields =
            event.fields.map { field ->
                val required = if (field.required) ", required = true" else ""
                "FieldSchema(\"${field.key}\", ${field.type.schema}$required)"
            }
        val arguments = listOf("Events.${event.constant}", "\"${event.method}\"") + fields
        // Only TrackNamespace and the event classes read a schema by name; the rest live in byKind alone.
        val visibility = if (event.kind in SDK_TRACKED) "private " else ""
        wrapped("    ", "${visibility}val ${event.constant} = EventSchema(", arguments, ")")
    }
    appendLine()
    appendLine("    val byKind: Map<String, EventSchema> =")
    appendLine("        listOf(")
    events.forEach { appendLine("            ${it.constant},") }
    appendLine("        ).associateBy { it.kind }")
    appendLine("}")
}

private fun StringBuilder.preamble(pkg: String) {
    appendLine(HEADER)
    appendLine()
    appendLine("package $pkg")
    appendLine()
}

private fun StringBuilder.kdoc(indent: String, lines: List<String>) {
    if (lines.size == 1 && "$indent/** ${lines[0]} */".length <= MAX_LINE) {
        appendLine("$indent/** ${lines[0]} */")
        return
    }
    appendLine("$indent/**")
    lines.forEach { appendLine(if (it.isEmpty()) "$indent *" else "$indent * $it") }
    appendLine("$indent */")
}

// On one line when it fits, else one item per line with a trailing comma: the layouts ktlint accepts.
private fun StringBuilder.wrapped(indent: String, open: String, items: List<String>, close: String) {
    val line = "$indent$open${items.joinToString(", ")}$close"
    if (line.length <= MAX_LINE) {
        appendLine(line)
        return
    }
    appendLine("$indent$open")
    items.forEach { appendLine("$indent    $it,") }
    appendLine("$indent$close")
}

/** Words of [text] as KDoc lines under [indent], lines after the first indented by [continuation]. */
private fun wrap(text: String, indent: String, continuation: String = ""): List<String> {
    val width = MAX_LINE - "$indent * ".length
    val lines = mutableListOf<String>()
    var current = ""
    fun prefix() = if (lines.isEmpty()) "" else continuation
    for (word in text.split(' ')) {
        val prefix = prefix()
        val candidate = if (current.isEmpty()) word else "$current $word"
        if (current.isNotEmpty() && (prefix + candidate).length > width) {
            lines += prefix + current
            current = word
        } else {
            current = candidate
        }
    }
    lines += prefix() + current
    return lines
}
